# Function to compute notification statistics from the in-memory queue
def get_notification_stats() -> dict:
    """Return summary statistics about the notification queue.

    Returns a dictionary containing:
        - total_queued: total number of notifications in the queue
        - by_type: mapping of notification type to count
        - unsent_count: number of notifications where sent_at is None
    """
    total_queued = len(_notification_queue)
    by_type: Dict[str, int] = {}
    unsent_count = 0

    for notif in _notification_queue:
        notif_type = notif.get("type")
        if notif_type is not None:
            by_type[notif_type] = by_type.get(notif_type, 0) + 1
        if notif.get("sent_at") is None:
            unsent_count += 1

    return {
        "total_queued": total_queued,
        "by_type": by_type,
        "unsent_count": unsent_count,
    }

